34	impl PagePool {
35	    pub(crate) fn new(capacity_pages: usize) -> Self {
36	        let free_list = (0..capacity_pages).rev().map(PageId).collect();
37	        Self {
38	            inner: Arc::new(PagePoolInner {
39	                capacity_pages,
40	                free_list: Mutex::new(free_list),
41	            }),
42	        }
43	    }
44	
45	    pub(crate) fn try_acquire_many(&self, n: usize) -> Option<OwnedPagePermit> {
46	        if n == 0 {
47	            return Some(OwnedPagePermit {
48	                inner: Arc::clone(&self.inner),
49	                pages: Vec::new(),
50	            });
51	        }
52	
53	        let mut free_list = self.inner.free_list.lock();
54	        if free_list.len() < n {
55	            return None;
56	        }
57	
58	        let mut pages = Vec::with_capacity(n);
59	        for _ in 0..n {
60	            pages.push(free_list.pop().expect("free_list length checked above"));
61	        }
62	
63	        Some(OwnedPagePermit {
64	            inner: Arc::clone(&self.inner),
65	            pages,
66	        })
67	    }
68	
69	    pub(crate) fn capacity_pages(&self) -> usize {
70	        self.inner.capacity_pages
71	    }
72	
73	    pub(crate) fn available_pages(&self) -> usize {
74	        self.inner.free_list.lock().len()
75	    }
76	}
