89	    /// Both permits must lease from the same pool; merging across pools would
90	    /// return pages to the wrong free list.
91	    pub(crate) fn absorb(&mut self, mut other: OwnedPagePermit) {
92	        assert!(
93	            Arc::ptr_eq(&self.inner, &other.inner),
94	            "absorb requires permits from the same pool"
95	        );
96	        self.pages.append(&mut other.pages);
97	    }
