99	    /// Try to acquire `n` more pages, appending them to this permit.
100	    /// Returns `true` on success. On failure the permit is unchanged.
101	    pub(crate) fn try_grow(&mut self, n: usize) -> bool {
102	        if n == 0 {
103	            return true;
104	        }
105	
106	        let mut free_list = self.inner.free_list.lock();
107	        if free_list.len() < n {
108	            return false;
109	        }
110	
111	        self.pages.reserve(n);
112	        for _ in 0..n {
113	            self.pages
114	                .push(free_list.pop().expect("free_list length checked above"));
115	        }
116	        true
